	UTF8	UTF-8 characters (default)
	Latin	Windows Latin1 (West European)
	Latin2	Windows Latin2 (Central European)
	Cyrillic	Windows Cyrillic
	Greek	Windows Greek
	Turkish	Windows Turkish
	Hebrew	Windows Hebrew
	Arabic	Windows Arabic
	Baltic	Windows Baltic
	Vietnam	Windows Vietnamese
	Thai	Windows Thai
	DOSLatinUS	DOS Latin US
	DOSLatin1	DOS Latin1
	DOSCyrillic	DOS Cyrillic
	MacRoman	Macintosh Roman
	MacLatin2	Macintosh Latin2 (Central Europe)
	MacCyrillic	Macintosh Cyrillic
	MacGreek	Macintosh Greek
	MacTurkish	Macintosh Turkish
	MacRomanian	Macintosh Romanian
	MacIceland	Macintosh Icelandic
	MacCroatian	Macintosh Croatian
ARGCEOF
}
