_choice_ext() {
    exiftool -listf | gawk 'NR > 1 { for (i = 1; i <= NF; i++) print $i }'
}

_choice_lang() {
    exiftool -lang | sed -e '1d' -e 's/^  //' | _argc_util_transform format=' - '
}
